const smsSenders = `-- name: SmsSenders :many
SELECT s.id, s.workspace_id, s.provider_id, s.kind, s.value, s.countries, s.throughput, s.provider_ref, s.added_by, s.added_at, s.removed_at, p.name AS provider_name, p.adapter AS provider_adapter
FROM sms_senders s
JOIN sms_providers p ON p.id = s.provider_id AND p.removed_at IS NULL
WHERE s.workspace_id = $1 AND s.removed_at IS NULL
ORDER BY p.connected_at, s.added_at, s.value
`

