const smsTestNumbers = `-- name: SmsTestNumbers :many
SELECT t.id, t.workspace_id, t.user_id, t.phone, t.added_by, t.added_at, coalesce(u.name, '')::text AS user_name, coalesce(r.name, '')::text AS role_name, coalesce(u.avatar_color, '')::text AS user_color
FROM sms_test_numbers t
LEFT JOIN users u ON u.id = t.user_id
LEFT JOIN workspace_members m ON m.user_id = t.user_id AND m.workspace_id = t.workspace_id
LEFT JOIN roles r ON r.id = m.role_id
WHERE t.workspace_id = $1
ORDER BY t.added_at
`

